/* Demonstrates using symlinkat() to create a symbolic link relative to an open directory file descriptor. */
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <sys/stat.h>

// Utility to clean up created files
static void cleanup(const char *dir, const char *link_full_path, const char *target) {
    if (link_full_path) unlink(link_full_path);
    if (target) unlink(target);
    if (dir) rmdir(dir);
}

int main(void) {
    const char *target_name = "data_source.txt";
    const char *link_dir_name = "safe_dir";
    const char *link_file_name = "alias_to_data";
    int dirfd = -1;
    char full_link_path[512];

    // 1. Setup: Create target file and secure directory
    if (creat(target_name, 0644) == -1) { perror("creat target"); return 1; }
    if (mkdir(link_dir_name, 0755) == -1) { 
        if (errno != EEXIST) { perror("mkdir"); cleanup(NULL, NULL, target_name); return 1; } 
    }

    // 2. Open the directory file descriptor for atomic path resolution
    dirfd = open(link_dir_name, O_RDONLY | O_DIRECTORY);
    if (dirfd == -1) { 
        perror("open dirfd"); 
        cleanup(link_dir_name, NULL, target_name); return 1; 
    }

    // 3. Create the symbolic link inside the directory referenced by dirfd
    // The link target remains 'data_source.txt'
    if (symlinkat(target_name, dirfd, link_file_name) == -1) {
        fprintf(stderr, "symlinkat failed: %s\n", strerror(errno));
        close(dirfd);
        cleanup(link_dir_name, NULL, target_name); 
        return 1;
    }

    printf("Successfully created symlink '%s/%s' pointing to '%s'.\n", 
           link_dir_name, link_file_name, target_name);

    // 4. Cleanup
    close(dirfd);
    snprintf(full_link_path, sizeof(full_link_path), "%s/%s", link_dir_name, link_file_name);
    cleanup(link_dir_name, full_link_path, target_name);

    return 0;
}
